function getDarktraceTranslation(key, lang) {
    return (darktraceTranslations[lang] && darktraceTranslations[lang][key]) ||
           (darktraceTranslations.en && darktraceTranslations.en[key]) || null;
}

function applyDarktraceTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.darktrace.") || key.startsWith("review.common."))) {
            const translation = getDarktraceTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} darktrace translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyDarktraceTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyDarktraceTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyDarktraceTranslations(window.i18n?.getCurrentLanguage() || "en");
}
